{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates & Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.08);--accent:#8be9fd;--muted:#cbd5e1;--glass-2:rgba(255,255,255,0.04)}
    html,body{height:100%;margin:0;font-family:Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; background:linear-gradient(180deg,#071029 0%, #0b1220 60%); color:#e6eef8}
    body{background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;border-radius:12px;background:linear-gradient(135deg,#1e3a8a,#06b6d4);display:flex;align-items:center;justify-content:center;font-weight:700;color:#021124;box-shadow:0 6px 16px rgba(2,17,36,0.6)}
    nav{display:flex;gap:16px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px}
    nav a:hover{background:var(--glass);color:#fff}
    .container{max-width:1100px;margin:24px auto;padding:20px}

    .hero{backdrop-filter:blur(8px);background:linear-gradient(135deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border-radius:14px;padding:28px;display:grid;grid-template-columns:1fr 360px;gap:18px;align-items:start}
    .hero h1{margin:0;font-size:clamp(20px,3vw,28px);line-height:1.05}
    .hero p{color:var(--muted);margin-top:8px}
    .hero .cta{margin-top:14px}
    .btn{background:linear-gradient(90deg,var(--accent),#7ef1c7);color:#04212a;padding:10px 14px;border-radius:10px;border:none;cursor:pointer;font-weight:600}

    .pricing{display:flex;flex-direction:column;gap:14px}
    .toggle{display:flex;align-items:center;gap:10px;background:var(--glass-2);padding:8px;border-radius:999px;width:220px}
    .toggle button{flex:1;background:none;border-radius:999px;border:none;padding:8px;color:var(--muted);cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,#0ea5a5,#7dd3fc);color:#012;box-shadow:0 6px 18px rgba(3,105,161,0.18)}

    .plans{display:grid;grid-template-columns:repeat(1,1fr);gap:12px}
    @media(min-width:820px){.plans{grid-template-columns:repeat(3,1fr)}}
    .plan{padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));box-shadow:inset 0 1px 0 rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03)}
    .plan h3{margin:0 0 6px 0}
    .price{font-size:22px;font-weight:700;color:#e6fff9}
    .muted{color:var(--muted);font-size:13px}

    .proof{margin-top:22px;padding:14px;border-radius:12px;background:linear-gradient(135deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));}
    .testi{display:flex;gap:12px;align-items:flex-start}
    .avatar{width:52px;height:52px;border-radius:12px;background:linear-gradient(135deg,#06b6d4,#7c3aed);display:flex;align-items:center;justify-content:center;font-weight:700;color:#001}
    .quote{font-style:italic;color:#dff7ff}
    .badges{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}
    .badge{background:rgba(255,255,255,0.03);padding:6px 8px;border-radius:8px;font-size:13px;color:var(--muted);position:relative}
    .badge:hover{cursor:help}
    .tooltip{position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#041024;color:#bfefff;padding:8px;border-radius:8px;font-size:13px;white-space:nowrap;display:none}
    .badge.show-tooltip .tooltip{display:block}

    footer{margin-top:30px;color:var(--muted);font-size:13px}
    .disclaimer{margin-top:12px;color:#b8d6e3;font-size:13px}

    /* small utility */
    .muted-block{color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">PP</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="about.html">Who I Am</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Rates & Plans</a>
      <a href="faq.html">Questions</a>
      <a href="book.html" style="background:var(--glass);color:#fff;border-radius:8px;padding:8px 10px">Schedule</a>
      <a href="contact.html">Get in Touch</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div>
        <h1>Transparent options for thoughtful therapy — choose what fits your rhythm.</h1>
        <p class="muted">A range of ways to work together: single sessions, short focused series, or a small cohort experience for ongoing peer-supported learning.</p>
        <div class="cta"><button class="btn" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button></div>
        <div style="margin-top:14px;color:var(--muted);font-size:13px">Phone: <a href="tel:{{PHONE}}" style="color:inherit">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}" style="color:inherit">{{EMAIL}}</a></div>
      </div>

      <aside class="pricing">
        <div class="toggle" role="tablist" aria-label="Pricing toggle">
          <button id="monthlyBtn" class="active" aria-pressed="true">Monthly</button>
          <button id="packageBtn" aria-pressed="false">Packages</button>
        </div>

        <div class="plans" id="plans">
          <div class="plan">
            <h3>Solo Session</h3>
            <div class="price"><span class="amount" data-monthly="150" data-package="140">$150</span><span class="muted"> / session</span></div>
            <div class="muted">Flexible scheduling. Pay per visit.</div>
            <div style="margin-top:10px"><button class="btn" onclick="location.href='book.html'">Request a Time</button></div>
          </div>

          <div class="plan">
            <h3>Clarity Series — 4</h3>
            <div class="price"><span class="amount" data-monthly="560" data-package="520">$560</span><span class="muted"> / series</span></div>
            <div class="muted">A compact set of sessions to focus on a specific concern.</div>
            <div style="margin-top:10px"><button class="btn" onclick="location.href='book.html'">Reserve Series</button></div>
          </div>

          <div class="plan">
            <h3>Guided Cohort</h3>
            <div class="price"><span class="amount" data-monthly="60" data-package="240">$60</span><span class="muted"> / month</span></div>
            <div class="muted">Small group learning and mutual support — limited enrollment each cycle.</div>
            <div style="margin-top:10px"><button class="btn" onclick="location.href='book.html'">Join a Cohort</button></div>
          </div>
        </div>
      </aside>
    </section>

    <section class="proof" aria-live="polite">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong>Proof Gallery</strong>
        <div class="muted">Voices from people who have worked with me</div>
      </div>
      <div id="testimonial" style="margin-top:12px" class="testi">
        <div class="avatar" id="avatar">KS</div>
        <div>
          <div class="quote" id="quote">"I came for clarity and left with practical patterns I could actually use in daily life."</div>
          <div class="muted-block" id="byline">— K. S., former cohort participant</div>

          <div class="badges" id="badges">
            <div class="badge" data-tip="Licensed Marriage & Family Therapist (LMFT)">LMFT<div class="tooltip">State-licensed clinician</div></div>
            <div class="badge" data-tip="Cohort facilitator">Facilitator<div class="tooltip">Leads small group work</div></div>
            <div class="badge" data-tip="Trauma-informed approach">Trauma-aware<div class="tooltip">Sensitive to past experiences</div></div>
          </div>
        </div>
      </div>
    </section>

    <section style="margin-top:18px;padding:14px;border-radius:12px;background:var(--glass);">
      <strong>About these options</strong>
      <p class="muted" style="margin:8px 0 0 0">Sessions are confidential and grounded in evidence-informed practice. I describe the scope of services clearly during our first conversation and together we decide what makes sense. I do not offer emergency services. If you are in immediate danger or a crisis, call 911 or your local emergency services, or go to your nearest emergency department.</p>
    </section>

    <footer>
      <div>Insurance: I provide receipts for out-of-network reimbursement on request. Sliding scale available for limited spaces; ask during intake.</div>
      <div class="disclaimer">Confidentiality: Clinical notes and session contents are confidential within typical professional and legal limits. We will review limits of confidentiality in our first meeting.</div>
    </footer>
  </main>

  <script>
    // Pricing toggle + animated numbers
    const monthlyBtn = document.getElementById('monthlyBtn');
    const packageBtn = document.getElementById('packageBtn');
    const amountEls = document.querySelectorAll('.amount');
    let currentMode = 'monthly';

    function animateValue(el, start, end, duration) {
      const startTime = performance.now();
      function frame(now){
        const progress = Math.min((now - startTime)/duration,1);
        const value = Math.round(start + (end - start)*progress);
        el.textContent = '$' + value;
        if(progress < 1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    function switchMode(mode){
      if(mode===currentMode) return;
      currentMode = mode;
      monthlyBtn.classList.toggle('active', mode==='monthly');
      packageBtn.classList.toggle('active', mode==='package');
      monthlyBtn.setAttribute('aria-pressed', mode==='monthly');
      packageBtn.setAttribute('aria-pressed', mode==='package');
      amountEls.forEach(el => {
        const from = parseInt(el.textContent.replace('$',''))||0;
        const to = parseInt(el.dataset[mode])||0;
        animateValue(el, from, to, 600);
      });
    }

    monthlyBtn.addEventListener('click',()=>switchMode('monthly'));
    packageBtn.addEventListener('click',()=>switchMode('package'));

    // Proof Gallery rotation + badges tooltip
    const testimonials = [
      {initials:'KS',quote:'"The small cohort felt like a steady workshop — I learned practical patterns and met people with similar questions."',by:'K. S., cohort participant',badges:['LMFT','Facilitator','Trauma-aware']},
      {initials:'AM',quote:'"Session work helped me name what was getting in the way and move forward without pressure."',by:'A. M., 1:1 client',badges:['LMFT','Continuing Ed','Group Leader']},
      {initials:'RB',quote:'"Clear structure and gentle challenge — I always left with one small experiment to try."',by:'R. B., series client',badges:['LMFT','Supervision','Ethics-trained']}
    ];

    let tIndex = 0;
    const quoteEl = document.getElementById('quote');
    const bylineEl = document.getElementById('byline');
    const avatarEl = document.getElementById('avatar');
    const badgesEl = document.getElementById('badges');

    function renderTestimonial(i){
      const t = testimonials[i];
      avatarEl.textContent = t.initials;
      quoteEl.textContent = t.quote;
      bylineEl.textContent = '— ' + t.by;
      badgesEl.innerHTML = '';
      t.badges.forEach(b=>{
        const d = document.createElement('div');
        d.className = 'badge';
        d.textContent = b;
        const tip = document.createElement('div');
        tip.className = 'tooltip';
        tip.textContent = b + ' — click for more';
        d.appendChild(tip);
        d.addEventListener('mouseenter', ()=>d.classList.add('show-tooltip'));
        d.addEventListener('mouseleave', ()=>d.classList.remove('show-tooltip'));
        badgesEl.appendChild(d);
      });
    }

    renderTestimonial(0);
    setInterval(()=>{ tIndex = (tIndex + 1) % testimonials.length; renderTestimonial(tIndex); }, 5000);

  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071225;--card:rgba(255,255,255,0.03);--accent:#8be9fd;--muted:#cbd5e1}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto; background:linear-gradient(180deg,#041426,#071225);color:#e6f3fb}
    .wrap{max-width:900px;margin:28px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center;padding:8px 0}
    nav a{color:var(--muted);text-decoration:none;margin-left:12px}

    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:16px;border-radius:12px}
    h1{margin:0 0 8px 0}

    .faq-item{border-radius:10px;padding:12px;margin-bottom:10px;background:rgba(255,255,255,0.01)}
    .q{display:flex;justify-content:space-between;align-items:center;cursor:pointer}
    .a{margin-top:8px;color:var(--muted);display:none}

    .proof-mini{margin-top:12px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
    .btn{background:linear-gradient(90deg,var(--accent),#7ef1c7);color:#04212a;padding:8px 12px;border-radius:8px;border:none;cursor:pointer}
    .muted{color:var(--muted);font-size:13px}

  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;gap:12px;align-items:center">
        <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#06b6d4,#7c3aed);display:flex;align-items:center;justify-content:center;font-weight:700;color:#022">PP</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div class="muted">Helpful details about working together</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="fees.html">Rates & Plans</a>
        <a href="book.html">Schedule</a>
      </nav>
    </header>

    <main class="grid">
      <section class="panel">
        <h1>Common Questions</h1>
        <p class="muted">Short answers to practical questions before you book. If you don't see what you need, reach out: <a href="mailto:{{EMAIL}}" style="color:inherit">{{EMAIL}}</a></p>

        <div id="faqs" style="margin-top:16px">
          <div class="faq-item">
            <div class="q"> <div>How do I know if therapy is right now?</div> <button class="toggle">+</button></div>
            <div class="a">I can help you explore that. A single session can be a low-commitment way to get a sense of fit and next steps.</div>
          </div>

          <div class="faq-item">
            <div class="q"> <div>Do you accept insurance?</div> <button class="toggle">+</button></div>
            <div class="a">I am out-of-network but provide a receipt (superbill) you can submit to many insurers for reimbursement. We can discuss billing at intake.</div>
          </div>

          <div class="faq-item">
            <div class="q"> <div>What is the cohort experience?</div> <button class="toggle">+</button></div>
            <div class="a">A small group that meets regularly with focused learning prompts and optional individual check-ins. It’s structured for shared learning, not group therapy.</div>
          </div>

          <div class="faq-item">
            <div class="q"> <div>How long are sessions?</div> <button class="toggle">+</button></div>
            <div class="a">Standard sessions are 50 minutes. Some focused sessions or administrative check-ins may be shorter; we'll confirm in scheduling.</div>
          </div>

          <div class="faq-item">
            <div class="q"> <div>Is this confidential?</div> <button class="toggle">+</button></div>
            <div class="a">Yes. Notes and session content are confidential within professional and legal limits. We'll review limits of confidentiality during intake.</div>
          </div>
        </div>
      </section>

      <aside>
        <div class="panel">
          <strong>Need a quick sense of fit?</strong>
          <p class="muted" style="margin-top:8px">Book a single session to discuss priorities and options. No long-term commitment required.</p>
          <div style="margin-top:12px"><button class="btn" onclick="location.href='book.html'">Arrange a First Visit</button></div>

          <div class="proof-mini" id="mini-proof" style="margin-top:14px">
            <strong>Voices</strong>
            <div id="mini-quote" style="margin-top:8px;color:#dff7ff">"Calm, practical, and constructive — I left with a clear next step."</div>
            <div style="margin-top:8px" class="muted">— M. R., series client</div>
          </div>

          <div style="margin-top:12px" class="muted">If you are in crisis, call 911 or local emergency services. This site is not a crisis resource.</div>
        </div>
      </aside>
    </main>

    <script>
      // FAQ expand/collapse logic + small testimonial rotation
      document.querySelectorAll('.faq-item').forEach(item=>{
        const btn = item.querySelector('.toggle');
        const ans = item.querySelector('.a');
        btn.addEventListener('click', ()=>{
          const open = ans.style.display === 'block';
          ans.style.display = open ? 'none' : 'block';
          btn.textContent = open ? '+' : '−';
        });
      });

      const miniQuotes = [
        '"Calm, practical, and constructive — I left with a clear next step." — M. R.',
        '"Small experiments that fit my life — not extra pressure." — J. S.',
        '"The cohort kept me curious and accountable in a kind way." — L. P.'
      ];
      const mqEl = document.getElementById('mini-quote');
      let mq = 0; setInterval(()=>{ mq = (mq+1)%miniQuotes.length; mqEl.textContent = miniQuotes[mq]; },4000);
    </script>
  </div>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Schedule — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071227;--card:rgba(255,255,255,0.03);--accent:#9be7ff;--muted:#bcd7e6}
    body{margin:0;font-family:Inter, system-ui, -apple-system; background:linear-gradient(180deg,#061426,#071227);color:#e6f6fb}
    .wrap{max-width:900px;margin:28px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:12px}

    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:18px;border-radius:12px}
    form{display:grid;grid-template-columns:1fr 260px;gap:16px}
    @media(max-width:820px){form{grid-template-columns:1fr}}
    label{display:block;margin-bottom:6px;font-size:13px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:inherit}
    .btn{background:linear-gradient(90deg,var(--accent),#7ef1c7);color:#04212a;padding:10px 12px;border-radius:10px;border:none;cursor:pointer}
    .note{color:var(--muted);font-size:13px;margin-top:10px}

    .slot{padding:8px;border-radius:8px;background:rgba(255,255,255,0.01);margin-bottom:8px;cursor:pointer}
    .slot.selected{outline:2px solid rgba(139,233,253,0.25)}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;gap:12px;align-items:center">
        <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#06b6d4,#7c3aed);display:flex;align-items:center;justify-content:center;font-weight:700;color:#022">PP</div>
        <div>
          <div style="font-weight:700">Book a session</div>
          <div class="muted">{{CITY}}, {{STATE}} • {{PHONE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="fees.html">Rates & Plans</a>
        <a href="contact.html">Get in Touch</a>
      </nav>
    </header>

    <main style="margin-top:18px">
      <div class="panel">
        <h2 style="margin:0 0 8px 0">Arrange a first visit</h2>
        <p class="note">Choose a preferred slot below, and tell me a bit about what brings you here. I will follow up to confirm and share intake details.</p>

        <form id="bookingForm" onsubmit="return submitForm(event)">
          <div>
            <label for="name">Your name</label>
            <input id="name" name="name" required>

            <label for="email" style="margin-top:10px">Email</label>
            <input id="email" name="email" type="email" required>

            <label for="phone" style="margin-top:10px">Phone</label>
            <input id="phone" name="phone" required>

            <label for="note" style="margin-top:10px">What would you like to focus on?</label>
            <textarea id="note" name="note" rows="5" placeholder="A few lines are fine"></textarea>

            <div style="margin-top:12px"><button class="btn" type="submit">Request this slot</button></div>
            <div class="note">By requesting, you agree to be contacted by email or phone about scheduling. This is not an appointment confirmation.</div>
          </div>

          <aside>
            <div style="margin-bottom:12px">
              <strong>Available slots</strong>
              <div class="note">Times shown in local time. If nothing fits, include preferred days in your message.</div>
            </div>

            <div id="slots">
              <div class="slot" data-slot="2026-03-02T09:00">Tue Mar 2 — 9:00 AM</div>
              <div class="slot" data-slot="2026-03-02T14:00">Tue Mar 2 — 2:00 PM</div>
              <div class="slot" data-slot="2026-03-03T11:00">Wed Mar 3 — 11:00 AM</div>
              <div class="slot" data-slot="2026-03-04T16:00">Thu Mar 4 — 4:00 PM</div>
            </div>

            <div style="margin-top:12px;padding-top:12px;border-top:1px dashed rgba(255,255,255,0.03)">
              <strong>Confidentiality & scope</strong>
              <div class="note" style="margin-top:6px">Sessions are confidential within legal limits. This practice does not provide emergency services. If you are in crisis, call 911 or your local emergency services.</div>
            </div>

          </aside>
        </form>
      </div>

      <div style="margin-top:12px;display:flex;gap:12px;flex-wrap:wrap">
        <div class="panel" style="flex:1"> 
          <strong>What to expect</strong>
          <p class="muted" style="margin-top:8px">A brief intake to understand priorities, followed by collaborative planning. I aim for clear agreements about scope, frequency, and practical next steps.</p>
        </div>
        <div class="panel" style="width:300px">
          <strong>Cancellation</strong>
          <p class="muted" style="margin-top:8px">If you need to change the appointment, please notify me as soon as possible so I can offer the slot to others.</p>
        </div>
      </div>
    </main>

  </div>

  <script>
    // Slot selection
    const slots = document.getElementById('slots');
    let selectedSlot = null;
    slots.addEventListener('click', (e)=>{
      const el = e.target.closest('.slot');
      if(!el) return;
      document.querySelectorAll('.slot').forEach(s=>s.classList.remove('selected'));
      el.classList.add('selected');
      selectedSlot = el.dataset.slot;
    });

    function submitForm(e){
      e.preventDefault();
      const data = {
        name: document.getElementById('name').value,
        email: document.getElementById('email').value,
        phone: document.getElementById('phone').value,
        note: document.getElementById('note').value,
        slot: selectedSlot
      };
